class Solution:
    def removeBoxes(self, boxes: List[int]) -> int:
        memo = {}
        def dp(l, r, k):
            if l > r:
                return 0
            while l + 1 <= r and boxes[l] == boxes[l + 1]:
                l += 1
                k += 1
            state = (l, r, k)
            if state in memo:
                return memo[state]
            res = (k + 1) * (k + 1) + dp(l + 1, r, 0)
            for m in range(l + 1, r + 1):
                if boxes[m] == boxes[l]:
                    res = max(res, dp(l + 1, m - 1, 0) + dp(m, r, k + 1))
            memo[state] = res
            return res
        return dp(0, len(boxes) - 1, 0)
