class Solution {
    int memo[100][100][100];
    int solve(vector<int>& boxes, int l, int r, int k) {
        if (l > r) return 0;
        while (l + 1 <= r && boxes[l] == boxes[l + 1]) {
            l++;
            k++;
        }
        if (memo[l][r][k] > 0) return memo[l][r][k];
        int res = (k + 1) * (k + 1) + solve(boxes, l + 1, r, 0);
        for (int m = l + 1; m <= r; ++m) {
            if (boxes[m] == boxes[l]) {
                res = max(res, solve(boxes, l + 1, m - 1, 0) + solve(boxes, m, r, k + 1));
            }
        }
        return memo[l][r][k] = res;
    }
public:
    int removeBoxes(vector<int>& boxes) {
        memset(memo, 0, sizeof(memo));
        return solve(boxes, 0, boxes.size() - 1, 0);
    }
};

class Solution {
    private int[][][] memo;
    public int removeBoxes(int[] boxes) {
        int n = boxes.length;
        memo = new int[n][n][n];
        return solve(boxes, 0, n - 1, 0);
    }
    private int solve(int[] boxes, int l, int r, int k) {
        if (l > r) return 0;
        while (l + 1 <= r && boxes[l] == boxes[l + 1]) {
            l++;
            k++;
        }
        if (memo[l][r][k] > 0) return memo[l][r][k];
        int res = (k + 1) * (k + 1) + solve(boxes, l + 1, r, 0);
        for (int m = l + 1; m <= r; ++m) {
            if (boxes[m] == boxes[l]) {
                res = Math.max(res, solve(boxes, l + 1, m - 1, 0) + solve(boxes, m, r, k + 1));
            }
        }
        return memo[l][r][k] = res;
    }
}

var removeBoxes = function(boxes) {
    const memo = new Map();
    function dp(l, r, k) {
        if (l > r) return 0;
        while (l + 1 <= r && boxes[l] === boxes[l + 1]) {
            l++;
            k++;
        }
        const key = (l << 16) | (r << 8) | k;
        if (memo.has(key)) return memo.get(key);
        let res = (k + 1) * (k + 1) + dp(l + 1, r, 0);
        for (let m = l + 1; m <= r; ++m) {
            if (boxes[m] === boxes[l]) {
                res = Math.max(res, dp(l + 1, m - 1, 0) + dp(m, r, k + 1));
            }
        }
        memo.set(key, res);
        return res;
    }
    return dp(0, boxes.length - 1, 0);
};
